import {itemName} from './guide.js';

export const weaponTypes={'Assault Rifle':'突擊步槍','Shotgun':'霰彈槍','Sniper Rifle':'狙擊步槍','Rocket Launcher':'火箭發射器','Missile Launcher':'飛彈發射器','Grenade Launcher':'榴彈發射器','Laser Rifle':'雷射步槍','Laser Cannon':'雷射砲','Energy Thrower':'能量投射器','Sword':'劍','Minigun':'機槍','Railgun':'磁軌砲','Satellite Weapon':'衛星武器','Special Weapon':'特殊武器'};
export const weaponScopes={all:'全部武器',base:'本體・白金',dlc:'Golden Storm DLC',bonus:'特典／另購'};
export const unlockKinds={initial:'初始裝備',mission:'任務完成','dlc-mission':'DLC 任務',bonus:'特典／另購','enemy-kills':'累計擊殺','drone-count':'Drone 收集'};
export const freshWeaponFilters=()=>({search:'',scope:'all',type:'all',rank:'all',kind:'all',mission:'all',unpurchased:false,locked:false,target:false,sort:'catalog'});
const normalize=value=>String(value??'').normalize('NFKC').toLocaleLowerCase().replace(/\bm0?(\d{1,2})\b/g,(_,n)=>'m'+String(n).padStart(2,'0'));
export function filterWeapons(weapons,progress,filters,{ignoreChecks=false}={}){
 const tokens=normalize(filters.search).trim().split(/\s+/).filter(Boolean);
 return weapons.filter(w=>{
  const state=progress.weapons[w.id]||{},text=normalize([itemName(w),w.nameJa,...(w.aliases||[]),w.type,weaponTypes[w.type],w.rank,w.unlockCondition,w.unlock.enemy,...(w.missionIds||[])].join(' '));
  return (filters.scope==='all'||w.contentGroup===filters.scope)&&tokens.every(token=>text.includes(token))&&(filters.type==='all'||w.type===filters.type)&&(filters.rank==='all'||w.rank===filters.rank)&&(filters.kind==='all'||w.unlock.kind===filters.kind)&&(filters.mission==='all'||w.missionIds.includes(filters.mission))&&(ignoreChecks||(!filters.unpurchased||!state.purchased)&&(!filters.locked||!state.unlocked)&&(!filters.target||state.target));
 });
}
export function sortWeapons(rows,sort){
 const ranks=['AA','A','B','C','D','E'];
 return [...rows].sort((a,b)=>sort==='name'?itemName(a).localeCompare(itemName(b)):sort==='rank'?ranks.indexOf(a.rank)-ranks.indexOf(b.rank):sort==='credits'?((a.price?.credits??Infinity)-(b.price?.credits??Infinity))||0:0);
}
export function unlockSummary(w){const u=w.unlock;if(u.kind==='dlc-mission')return `${u.extraMissionId.toUpperCase()} · ${u.reportedDifficulty||'難度見詳情'}`;if(u.kind==='mission')return `${u.missionId.toUpperCase()} · ${u.reportedDifficulty||u.minimumDifficulty||'難度見詳情'}（表列）`;if(u.kind==='enemy-kills')return `${u.enemy} × ${u.killCount.toLocaleString()}`;if(u.kind==='drone-count')return `Drone × ${u.droneCount}`;return unlockKinds[u.kind]||'條件見詳情';}

export function weaponCatalogHtml({weapons,progress,filters,held,opened,adviceNotes=[],weaponAdviceHtml=()=>'',missions,trophies,droneCount,advancedOpen=false,escape,option,sourceLinks,button}){
 const matched=filterWeapons(weapons,progress,filters),eligible=filterWeapons(weapons,progress,filters,{ignoreChecks:true}),retained=eligible.filter(w=>held.has(w.id)&&!matched.includes(w)),rows=sortWeapons([...matched,...retained],filters.sort),owned=weapons.filter(w=>progress.weapons[w.id]?.purchased).length,base=weapons.filter(w=>w.platinumRequired),baseOwned=base.filter(w=>progress.weapons[w.id]?.purchased).length,scopeRows=weapons.filter(w=>filters.scope==='all'||w.contentGroup===filters.scope);
 const select=(key,label,options)=>`<label>${label}<select id="weapon-filter-${key}" data-weapon-filter="${key}">${option(options,filters[key])}</select></label>`;
 const toggle=(key,label)=>`<label class="check-label"><input id="weapon-filter-${key}" type="checkbox" data-weapon-filter="${key}" ${filters[key]?'checked':''}>${label}</label>`;
 const typeOptions=[['all','全部類型'],...Object.entries(weaponTypes).filter(([type])=>weapons.some(w=>w.type===type))];
 const typeButton=(type,label)=>{const list=scopeRows.filter(w=>type==='all'||w.type===type),n=list.filter(w=>progress.weapons[w.id]?.purchased).length;return `<button data-weapon-type="${escape(type)}" aria-pressed="${filters.type===type}"><span>${escape(label)}</span><small>${n}/${list.length}</small></button>`;};
 return `<div class="arsenal-intro"><div><h2>武器購買清單</h2><p>本體持有 <strong id="arsenal-base-count">${baseOwned} / ${base.length}</strong> · 全圖鑑 ${owned} / ${weapons.length}</p></div><div class="actions"><button data-go="advice">先看選槍心得</button><button data-go="resources">資源規劃 →</button></div></div><p class="catalog-notice">白金只計本體持有，仍需核對 PSN。未知成本與未核英文見詳情。</p><div class="weapon-scope-tabs" aria-label="武器內容範圍">${Object.entries(weaponScopes).map(([scope,label])=>`<button data-weapon-scope="${scope}" aria-pressed="${filters.scope===scope}">${escape(label)} <small>${weapons.filter(w=>scope==='all'||w.contentGroup===scope).length}</small></button>`).join('')}</div><div class="arsenal-layout"><nav class="weapon-type-rail" aria-label="武器類型">${typeButton('all','全部武器')}${typeOptions.slice(1).map(([type,label])=>typeButton(type,label)).join('')}<p>持有數 / 收錄數</p></nav><div class="arsenal-main"><div class="weapon-filters"><label class="weapon-search">搜尋<input id="weapon-search" type="search" data-weapon-filter="search" value="${escape(filters.search)}" placeholder="名稱、敵人、M01…"></label><div class="weapon-mobile-type">${select('type','類型',typeOptions)}</div>${select('rank','等級',[['all','全部等級'],...['AA','A','B','C','D','E'].filter(rank=>weapons.some(w=>w.rank===rank)).map(rank=>[rank,rank])])}<details class="weapon-advanced" id="weapon-advanced" ${advancedOpen?'open':''}><summary>解鎖、任務與持有篩選${[filters.kind!=='all',filters.mission!=='all',filters.unpurchased,filters.locked,filters.target].filter(Boolean).length?' · 已套用':''}</summary><div class="weapon-advanced-selects">${select('kind','解鎖方式',[['all','全部方式'],...Object.entries(unlockKinds)])}${select('mission','關聯任務',[['all','全部任務'],...missions.filter(m=>weapons.some(w=>w.missionIds.includes(m.id))).map(m=>[m.id,m.id.toUpperCase()+' · '+m.officialName])])}</div><div class="weapon-filter-checks">${toggle('unpurchased','只看未持有')}${toggle('locked','只看未解鎖')}${toggle('target','只看規劃中')}</div></details></div><div class="weapon-list-bar"><button data-weapon-reset>清除篩選</button><p id="weapon-result-count" role="status">${matched.length} 款符合${retained.length?` · 另保留 ${retained.length} 款剛勾選項目`:''}</p>${select('sort','排序',[['catalog','圖鑑順序'],['rank','等級由高至低'],['credits','Credits 由少至多'],['name','名稱 A–Z']])}</div><div id="weapon-results">${rows.length?rows.map(w=>{
  const state=progress.weapons[w.id]||{},open=opened.has(w.id),price=w.price||{},priceKnown=['credits','red','blue','yellow'].every(k=>Number.isSafeInteger(price[k])),checkbox=(key,label)=>`<label class="weapon-check"><input type="checkbox" id="${escape(w.id)}-${key}" data-weapon="${escape(w.id)}" data-key="${key}" ${state[key]?'checked':''}><span>${label}</span></label>`;
  return `<article data-content-scope="${escape(w.contentGroup)}" class="weapon-row ${state.purchased?'owned':''}" id="weapon-${escape(w.id)}"><div class="weapon-line"><div class="weapon-identity"><span class="weapon-rank">${escape(w.rank||'—')}</span><div><h3>${escape(itemName(w))}</h3><small>${escape(weaponTypes[w.type]||w.type)}${w.contentGroup!=='base'?' · '+escape(w.contentGroup==='dlc'?'DLC':'特典'):''}${state.target?' · 規劃中':''}</small></div></div><div class="weapon-unlock"><span>${escape(unlockSummary(w))}</span><small>${Number.isSafeInteger(price.credits)?price.credits.toLocaleString()+' Credits'+(!priceKnown?' · Gems 部分待查':''):'價格待查證'}${w.warning?' · 注意事項見詳情':''}</small></div><div class="weapon-ticks">${checkbox('unlocked','解鎖')}${checkbox('purchased','持有')}</div><button class="weapon-peek" data-weapon-peek="${escape(w.id)}" aria-expanded="${open}" aria-controls="detail-${escape(w.id)}">${open?'收合':'詳情'} <span aria-hidden="true">${open?'−':'+'}</span></button></div><div class="weapon-detail" id="detail-${escape(w.id)}" ${open?'':'hidden'}><div>${weaponAdviceHtml(adviceNotes.find(row=>row.weaponId===w.id),{escape,sourceLinks})}<h4>解鎖與取得</h4><p class="weapon-content-label">${escape(weaponScopes[w.contentGroup]||w.contentGroup)}${w.platinumRequired?' · 計入本體全武器條件':' · 不計入本體全武器條件'}</p><p>${escape(w.unlockCondition)}</p>${w.unlock.kind==='drone-count'?`<p>Drone 條件：${droneCount} / ${w.unlock.droneCount}。請另行核對遊戲內解鎖。</p>`:''}<p>${escape(w.recommendation||'推薦用途尚未逐項查證；請先看本關出擊需求。')}</p>${w.warning?`<p class="warning">${escape(w.warning)}</p>`:''}<div class="actions">${w.missionIds.map(id=>button('roadmap',id.toUpperCase(),id)).join('')}</div></div><div><h4>購買資源</h4><dl class="weapon-price">${Object.entries({credits:'Credits',red:'紅色 Gems',blue:'藍色 Gems',yellow:'黃色 Gems'}).map(([key,label])=>`<div><dt>${label}</dt><dd>${Number.isSafeInteger(price[key])?price[key].toLocaleString():'待查證'}</dd></div>`).join('')}</dl>${checkbox('target','加入資源規劃')}<p class="unknown">持有勾選不會代替 PSN 跳盃，也不會自動勾選解鎖。</p></div><div class="weapon-evidence"><p class="unknown">${escape(w.nameVerification||'名稱尚未逐項實機核對')}${w.nameJa?' · 日文：'+escape(w.nameJa):''}</p><div class="sources">${(w.trophyIds||[]).map(id=>`<a href="?view=trophies#trophy-${escape(id)}" data-trophy-link="${escape(id)}">${escape(trophies.find(t=>t.id===id)?.officialName||id)}</a>`).join('')}</div>${w.evidence?.length?`<p class="unknown">查證：${escape(w.evidence[0].section)} · 來源行 ${w.evidence[0].line}。條件／成本為文字轉錄，尚未實機驗證。</p>`:''}${sourceLinks(w.sourceIds)}</div></div></article>`;
 }).join(''):'<div class="empty"><p>沒有符合條件的武器。</p><button data-weapon-reset>清除篩選，查看全部</button></div>'}</div></div></div>`;
}
